{"filePath":"/tmp/opencode/make_report.py","content":"import json
import re
import subprocess
import sys
from pathlib import Path

root = Path('/testbed')
sys.path.insert(0, str(root))
from parser import parse_header, MalformedHeaderError

# 1. Run pytest
proc = subprocess.run(
    [sys.executable, '-m', 'pytest', 'incoming/repro_tests', '-v'],
    cwd=root,
    capture_output=True,
    text=True,
)
out = proc.stdout
tests = {}
for m in re.finditer(r'^.*::(\w+)\s+(PASSED|FAILED|ERROR)\b', out, re.M):
    tests[m.group(1)] = m.group(2).lower()
# Overall from pytest summary line / exit code
passed = proc.returncode == 0 and 'failed' not in out and 'error' not in out and tests

# Expected malformed-header exception (actually captured from the parser)
malformed_input = (root / 'incoming/repro_tests/malformed_header.txt').read_text().strip()
try:
    parse_header(malformed_input)
    exc = {'type': None, 'message': None, 'raised': False}
except MalformedHeaderError as e:
    exc = {
        'type': type(e).__name__,
        'message': str(e),
        'raised': True,
    }

# Verify parser behavior for the two inputs (actual results)
def probe(line):
    try:
        result = parse_header(line)
        return {'input': line, 'status': 'ok', 'result': list(result)}
    except MalformedHeaderError as e:
        return {
            'input': line,
            'status': 'raised',
            'exception': {'type': type(e).__name__, 'message': str(e)},
        }

verification = [
    probe('Content-Length 42'),
    probe('Content-Length: 42'),
]

report = {
    'exception': {
        'type': exc['type'],
        'message': exc['message'],
    },
    'tests': tests,
    'passed': bool(passed),
    'inputs': {
        'malformed': malformed_input,
    },
    'verification': verification,
    'pytest_summary': [
        l.strip() for l in out.splitlines()
        if l.strip().startswith('=====') or 'passed' in l or 'failed' in l
    ],
}

artifacts = root / 'artifacts'
artifacts.mkdir(exist_ok=True)
(artifacts / 'parser_repro.json').write_text(json.dumps(report, indent=2) + '\n')
print(json.dumps(report, indent=2))
print('---')
print('pytest exit code:', proc.returncode)
"}

